package main

import "testing"

func TestClassifyFileRole_PathConventions(t *testing.T) {
	cases := []struct {
		name string
		path string
		want FileRole
	}{
		// Generated by path convention.
		{"proto pb.go", "api/handlers/graph/graph.pb.go", FileRoleGenerated},
		{"connect.go", "packages/proto/gen/go/x/graph.connect.go", FileRoleGenerated},
		{"generated ts", "ui/src/strings.generated.ts", FileRoleGenerated},
		{"gen dir", "packages/proto/gen/go/x/shared/shared.go", FileRoleGenerated},

		// Test files (delegated to IsTestFilePath).
		{"go test", "api/endpoints_test.go", FileRoleTest},
		{"ts spec", "ui/src/foo.spec.tsx", FileRoleTest},
		{"tests dir", "api/tests/integration.go", FileRoleTest},

		// Test support (hand-written scaffolding, no marker).
		{"mocks dir", "internal/foo/mocks/client.go", FileRoleTestSupport},
		{"fixtures dir", "api/fixtures/sample.go", FileRoleTestSupport},
		{"testutil dir", "api/testutil/helpers.go", FileRoleTestSupport},
		{"testdata dir", "api/testdata/golden.go", FileRoleTestSupport},

		// Declarative wiring / const registries.
		{"endpoints.go", "api/handlers/campaign/endpoints.go", FileRoleDeclarativeWiring},
		{"module.go", "api/handlers/graph/module.go", FileRoleDeclarativeWiring},
		{"register.go", "cli/cmd/graph/register.go", FileRoleDeclarativeWiring},
		{"cli handlers.go", "cli/cmd/graph/handlers.go", FileRoleDeclarativeWiring},
		{"selectors.ts", "ui/src/state/selectors.ts", FileRoleDeclarativeWiring},

		// Composition roots.
		{"handler.go", "api/handler.go", FileRoleCompositionRoot},
		{"app modules.go", "api/app/modules.go", FileRoleCompositionRoot},
		{"registry.go", "internal/modules/registry.go", FileRoleCompositionRoot},
		{"main.go", "api/main.go", FileRoleCompositionRoot},

		// Negatives — ordinary production code.
		{"service.go", "api/service.go", FileRoleProduction},
		{"api handlers.go (not cli)", "api/handlers.go", FileRoleProduction},
		{"domain file", "internal/campaign/campaign.go", FileRoleProduction},
	}

	for _, tc := range cases {
		t.Run(tc.name, func(t *testing.T) {
			if got := ClassifyFileRole(tc.path, nil); got != tc.want {
				t.Errorf("ClassifyFileRole(%q) = %v, want %v", tc.path, got, tc.want)
			}
		})
	}
}

func TestClassifyFileRole_GeneratedMarkers(t *testing.T) {
	goMarker := []byte("// Code generated by protoc-gen-go. DO NOT EDIT.\n\npackage x\n")
	autoMarker := []byte("/* AUTO-GENERATED FILE — do not edit by hand */\nexport const x = 1\n")
	plain := []byte("package main\n\nfunc main() {}\n")

	// A production-looking path with a generated marker is Generated.
	if got := ClassifyFileRole("api/service.go", goMarker); got != FileRoleGenerated {
		t.Errorf("go marker: got %v, want Generated", got)
	}
	if got := ClassifyFileRole("ui/src/strings.ts", autoMarker); got != FileRoleGenerated {
		t.Errorf("auto marker: got %v, want Generated", got)
	}
	// No marker, plain bytes — stays Production.
	if got := ClassifyFileRole("api/service.go", plain); got != FileRoleProduction {
		t.Errorf("plain bytes: got %v, want Production", got)
	}
	// A hand-written mock (no marker) stays TestSupport even with bytes present.
	if got := ClassifyFileRole("internal/foo/mocks/client.go", plain); got != FileRoleTestSupport {
		t.Errorf("hand-written mock: got %v, want TestSupport", got)
	}
}

func TestIsTestFilePathStillWorks(t *testing.T) {
	// IsTestFilePath remains a thin, callable wrapper (not forked).
	if !IsTestFilePath("api/foo_test.go") {
		t.Error("IsTestFilePath should report _test.go as a test file")
	}
	if IsTestFilePath("api/foo.go") {
		t.Error("IsTestFilePath should not report foo.go as a test file")
	}
}

func TestFileRoleString(t *testing.T) {
	cases := map[FileRole]string{
		FileRoleProduction:        "production",
		FileRoleTest:              "test",
		FileRoleTestSupport:       "test-support",
		FileRoleGenerated:         "generated",
		FileRoleCompositionRoot:   "composition-root",
		FileRoleDeclarativeWiring: "declarative-wiring",
	}
	for role, want := range cases {
		if got := role.String(); got != want {
			t.Errorf("FileRole(%d).String() = %q, want %q", role, got, want)
		}
	}
}
